CREATE TABLE #concept_count_data
DISTKEY(subject_id)
AS
SELECT
cohort_definition_id,
	 subject_id ,
	cohort_start_date,
	covariate_id,
	concept_count
FROM
(
	SELECT 
		CAST(visit_concept_id AS BIGINT) * 1000 + 923 AS covariate_id,
		cohort_definition_id,
		subject_id,
		cohort_start_date,
		COUNT(*) AS concept_count
	FROM @characterization_cohort cohort
	INNER JOIN @cdm_database_schema.visit_occurrence
		ON cohort.subject_id = visit_occurrence.person_id
	WHERE visit_start_date <= DATEADD(DAY,CAST(0 as int),cohort.cohort_start_date)
		AND visit_end_date >= DATEADD(DAY,CAST(-365 as int),cohort.cohort_start_date)
		AND visit_concept_id != 0
	GROUP BY 
		visit_concept_id,
		cohort_definition_id,
		subject_id,
		cohort_start_date
	) raw_data;
CREATE TABLE #concept_count_stats
 DISTSTYLE ALL
AS
WITH
t1 
AS
(
	SELECT cohort_definition_id,
		COUNT(*) AS cnt 
	FROM @characterization_cohort 
	GROUP BY cohort_definition_id
	),
t2 AS (
	SELECT cohort_definition_id,
		COUNT(*) AS cnt, 
		covariate_id,
		MIN(concept_count) AS min_concept_count, 
		MAX(concept_count) AS max_concept_count, 
		SUM(CAST(concept_count AS BIGINT)) AS sum_concept_count,
		SUM(CAST(concept_count AS BIGINT) * CAST(concept_count AS BIGINT)) AS squared_concept_count
	FROM #concept_count_data
	GROUP BY cohort_definition_id
		,covariate_id
	)
SELECT
t1.cohort_definition_id,
	CASE WHEN t2.cnt = t1.cnt THEN t2.min_concept_count ELSE 0 END AS min_value,
	t2.max_concept_count AS max_value,
	covariate_id,
	CAST(t2.sum_concept_count / (1.0 * t1.cnt) AS FLOAT) AS average_value,
	CAST(CASE
		WHEN t2.cnt = 1 THEN 0 
		ELSE SQRT((1.0 * t2.cnt*t2.squared_concept_count - 1.0 * t2.sum_concept_count*t2.sum_concept_count) / (1.0 * t2.cnt*(1.0 * t2.cnt - 1))) 
	END AS FLOAT) AS standard_deviation,
	t2.cnt AS count_value,
	t1.cnt - t2.cnt AS count_no_value,
	t1.cnt AS population_size
FROM
t1
INNER JOIN t2
	ON t1.cohort_definition_id = t2.cohort_definition_id;
CREATE TABLE #concept_count_prep
 DISTSTYLE ALL
AS
SELECT
cohort_definition_id, 
	concept_count,
	COUNT(*) AS total,
	covariate_id,
	ROW_NUMBER() OVER (PARTITION BY cohort_definition_id, covariate_id  ORDER BY concept_count ) AS rn
FROM
#concept_count_data
GROUP BY cohort_definition_id,
	covariate_id,
	concept_count;
CREATE TABLE #concept_count_prep2	
 DISTSTYLE ALL
AS
SELECT
s.cohort_definition_id,
	s.concept_count,
	s.covariate_id,
	SUM(p.total) AS accumulated
FROM
#concept_count_prep s
INNER JOIN #concept_count_prep p
	ON p.rn <= s.rn
		AND p.cohort_definition_id = s.cohort_definition_id
		AND p.covariate_id = s.covariate_id
GROUP BY s.cohort_definition_id,
	s.covariate_id,
	s.concept_count;
