INSERT INTO #cov_ref (
	covariate_id,
	covariate_name,
	analysis_id,
	concept_id
	)
SELECT covariate_id,
	CAST(CONCAT('age group: ',CONCAT(RIGHT(CONCAT('   ', CAST(CAST(5 * (covariate_id - 3) / 1000 AS INTEGER) AS VARCHAR)), 3),CONCAT(' - ',RIGHT(CONCAT('   ', CAST((CAST(5 * (covariate_id - 3) / 1000 AS INTEGER)) + 4 AS VARCHAR)), 3)
		))) AS VARCHAR(512)) AS covariate_name,
	3 AS analysis_id,
	0 AS concept_id
FROM (
	SELECT DISTINCT covariate_id
	FROM #cov_8
	) t1;
