	CAST('Demographics' AS VARCHAR(20)) AS domain_id,
	CAST(NULL AS INT) AS start_day,
	CAST(NULL AS INT) AS end_day,
	CAST('Y' AS VARCHAR(1)) AS is_binary,
	CAST(NULL AS VARCHAR(1)) AS missing_means_zero;
