CREATE TABLE #dem_time_data
DISTKEY(subject_id)
AS
SELECT
 subject_id ,
	cohort_definition_id,
	cohort_start_date,
	days
FROM
(
	SELECT 
		cohort_definition_id,
		subject_id,
		cohort_start_date,	
		DATEDIFF(DAY, op.observation_period_start_date, cohort_start_date) AS days
	FROM @characterization_cohort cohort
	INNER JOIN @cdm_database_schema.observation_period op
		ON op.person_id = cohort.subject_id 
		AND op.observation_period_start_date <= cohort_start_date
		AND op.observation_period_end_date >= cohort_start_date
	) raw_data;
CREATE TABLE #dem_time_stats
 DISTSTYLE ALL
AS
WITH
t1 
AS
(
	SELECT cohort_definition_id,
		COUNT(*) AS cnt 
	FROM @characterization_cohort 
	GROUP BY cohort_definition_id
	),
t2 AS (
	SELECT cohort_definition_id,
		COUNT(*) AS cnt, 
		MIN(days) AS min_days, 
		MAX(days) AS max_days, 
		SUM(CAST(days AS BIGINT)) AS sum_days, 
		SUM(CAST(days AS BIGINT) * CAST(days AS BIGINT)) AS squared_days 
	FROM #dem_time_data
	GROUP BY cohort_definition_id
	)
SELECT
t1.cohort_definition_id,
	CASE WHEN t2.cnt = t1.cnt THEN t2.min_days ELSE 0 END AS min_value,
	t2.max_days AS max_value,
	CAST(t2.sum_days / (1.0 * t1.cnt) AS FLOAT) AS average_value,
	CAST(CASE WHEN t2.cnt = 1 THEN 0 ELSE SQRT((1.0 * t2.cnt*t2.squared_days - 1.0 * t2.sum_days*t2.sum_days) / (1.0 * t2.cnt*(1.0 * t2.cnt - 1))) END AS FLOAT) AS standard_deviation,
	t2.cnt AS count_value,
	t1.cnt - t2.cnt AS count_no_value,
	t1.cnt AS population_size
FROM
t1
INNER JOIN t2
	ON t1.cohort_definition_id = t2.cohort_definition_id;
CREATE TABLE #dem_time_prep
 DISTSTYLE ALL
AS
SELECT
cohort_definition_id,
	days,
	COUNT(*) AS total,
	ROW_NUMBER() OVER (PARTITION BY cohort_definition_id  ORDER BY days ) AS rn
FROM
#dem_time_data
GROUP BY cohort_definition_id,
	days;
CREATE TABLE #dem_time_prep2	
 DISTSTYLE ALL
AS
SELECT
s.cohort_definition_id,
	s.days,
	SUM(p.total) AS accumulated
FROM
#dem_time_prep s
INNER JOIN #dem_time_prep p
	ON p.rn <= s.rn
		AND p.cohort_definition_id = s.cohort_definition_id
GROUP BY s.cohort_definition_id,
	s.days;
CREATE TABLE #cov_10
 DISTSTYLE ALL
AS
SELECT
o.cohort_definition_id,
	CAST(1000 + 8 AS BIGINT) AS covariate_id,
	o.count_value,
	o.min_value,
	o.max_value,
	CAST(o.average_value AS FLOAT) average_value,
	CAST(o.standard_deviation AS FLOAT) standard_deviation,
	CASE 
		WHEN .50 * o.population_size < count_no_value THEN 0
		ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .50 * o.population_size THEN days	END) 
		END AS median_value,
	CASE 
		WHEN .10 * o.population_size < count_no_value THEN 0
		ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .10 * o.population_size THEN days	END) 
		END AS p10_value,		
	CASE 
		WHEN .25 * o.population_size < count_no_value THEN 0
		ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .25 * o.population_size THEN days	END) 
		END AS p25_value,	
	CASE 
		WHEN .75 * o.population_size < count_no_value THEN 0
		ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .75 * o.population_size THEN days	END) 
		END AS p75_value,	
	CASE 
		WHEN .90 * o.population_size < count_no_value THEN 0
		ELSE MIN(CASE WHEN p.accumulated + count_no_value >= .90 * o.population_size THEN days	END) 
		END AS p90_value		
FROM
#dem_time_prep2 p
INNER JOIN #dem_time_stats o
	ON p.cohort_definition_id = o.cohort_definition_id
GROUP BY o.count_value,
	o.count_no_value,
	o.min_value,
	o.max_value,
	o.average_value,
	o.standard_deviation,
	o.population_size,
	o.cohort_definition_id;
TRUNCATE TABLE #dem_time_data;
DROP TABLE #dem_time_data;
TRUNCATE TABLE #dem_time_stats;
DROP TABLE #dem_time_stats;
TRUNCATE TABLE #dem_time_prep;
DROP TABLE #dem_time_prep;
TRUNCATE TABLE #dem_time_prep2;
DROP TABLE #dem_time_prep2;	
-- Reference construction
INSERT INTO #cov_ref (
	covariate_id,
	covariate_name,
	analysis_id,
	concept_id
	)
SELECT covariate_id,
	CAST('observation time (days) prior to index' AS VARCHAR(512)) AS covariate_name,
	8 AS analysis_id,
	0 AS concept_id
FROM (
	SELECT DISTINCT covariate_id
	FROM #cov_10
	) t1;
INSERT INTO #analysis_ref (
	analysis_id,
	analysis_name,
	domain_id,
	start_day,
	end_day,
	is_binary,
	missing_means_zero
	)
SELECT 8 AS analysis_id,
	CAST('DemographicsPriorObservationTime' AS VARCHAR(512)) AS analysis_name,
	CAST('Demographics' AS VARCHAR(20)) AS domain_id,
	CAST(NULL AS INT) AS start_day,
	CAST(NULL AS INT) AS end_day,
	CAST('N' AS VARCHAR(1)) AS is_binary,
	CAST('Y' AS VARCHAR(1)) AS missing_means_zero;
DROP TABLE IF EXISTS #groups;
CREATE TABLE #groups
 DISTSTYLE ALL
AS
SELECT
DISTINCT descendant_concept_id,
  ancestor_concept_id
FROM
@cdm_database_schema.concept_ancestor
INNER JOIN @cdm_database_schema.concept
	ON ancestor_concept_id = concept_id
WHERE ((vocabulary_id = 'ATC'
		AND CHAR_LENGTH(concept_code) IN (1, 3, 4, 5))
	OR (standard_concept = 'S' 
		AND concept_class_id = 'Ingredient'
		AND domain_id = 'Drug'))
	AND concept_id != 0
;
-- Feature construction
CREATE TABLE #cov_11
 DISTSTYLE ALL
AS
SELECT
CAST(ancestor_concept_id AS BIGINT) * 1000 + 410 AS covariate_id,
	cohort_definition_id,
	COUNT(*) AS sum_value
FROM
(
	SELECT DISTINCT ancestor_concept_id,
		cohort_definition_id,
		cohort.subject_id,
		cohort.cohort_start_date
	FROM @characterization_cohort cohort
	INNER JOIN @cdm_database_schema.drug_era
		ON cohort.subject_id = drug_era.person_id
	INNER JOIN #groups
		ON drug_concept_id = descendant_concept_id
	WHERE drug_era_start_date <= DATEADD(DAY,CAST(0 as int),cohort.cohort_start_date)
AND 
drug_era_end_date 
>= DATEADD(DAY,CAST(-365 as int),cohort.cohort_start_date)
		AND drug_concept_id != 0
) temp
GROUP BY cohort_definition_id,
	ancestor_concept_id
;
TRUNCATE TABLE #groups;
DROP TABLE #groups;
-- Reference construction
INSERT INTO #cov_ref (
	covariate_id,
	covariate_name,
	analysis_id,
	concept_id
	)
SELECT covariate_id,
	CAST(CONCAT('drug_era group (DrugGroupEraLongTerm) during day -365 through 0 days relative to index: ', CASE WHEN concept_name IS NULL THEN 'Unknown concept' ELSE concept_name END ) AS VARCHAR(512)) AS covariate_name,
	410 AS analysis_id,
	CAST((covariate_id - 410) / 1000 AS INT) AS concept_id
FROM (
	SELECT DISTINCT covariate_id
	FROM #cov_11
	) t1
LEFT JOIN @cdm_database_schema.concept
	ON concept_id = CAST((covariate_id - 410) / 1000 AS INT);
