	)
SELECT covariate_id,
	CAST(CONCAT('drug_era group (DrugGroupEraAnyTimePrior) any time prior through 0 days relative to index: ', CASE WHEN concept_name IS NULL THEN 'Unknown concept' ELSE concept_name END ) AS VARCHAR(512)) AS covariate_name,
